class SecureKey:
    """Minimal production-compatible SecureKey implementation."""

    def __init__(
        self,
        key_id: str,
        public_key: bytes,
        ciphertext: bytes,
        shared_secret: bytes,
        created_at: float,
        expires_at: float,
    ):
        self.key_id = key_id
        self.public_key = public_key
        self.ciphertext = ciphertext
        self.shared_secret = shared_secret
        self.created_at = created_at
        self.expires_at = expires_at

    @property
    def is_expired(self, now: Optional[float] = None) -> bool:
        """Check expiry against current or provided timestamp."""
        current = now if now is not None else time.time()
        return current >= self.expires_at


class KeyRotationBuffer:
    """
    Production-compatible bounded key rotation buffer.

    Implements INV-002:
    - Hard capacity limit (MAX_ACTIVE_KEYS = 1024)
    - Expired key cleanup on access and explicit rotation
    - TTL boundary semantics (expiry at exact threshold)
    - Thread-safe / async-safe operations
    """

    MAX_ACTIVE_KEYS = 1024
    DEFAULT_TTL_SECONDS = 300  # 5 minutes

    def __init__(self, max_keys: int = MAX_ACTIVE_KEYS, ttl_seconds: int = DEFAULT_TTL_SECONDS):
        if max_keys <= 0:
            raise ValueError("max_keys must be positive")
        if ttl_seconds <= 0:
            raise ValueError("ttl_seconds must be positive")
        self._max_keys = max_keys
        self._ttl_seconds = ttl_seconds
        self._keys: Dict[str, SecureKey] = {}
        self._lock = asyncio.Lock()

    async def add_key(self, key: SecureKey) -> bool:
        """Add a key to the buffer. Returns True if accepted, False if rejected (capacity full)."""
        async with self._lock:
            # Clean expired keys first
            await self._purge_expired_locked()
            if len(self._keys) >= self._max_keys:
                return False
            self._keys[key.key_id] = key
            return True

    async def get_key(self, key_id: str) -> Optional[SecureKey]:
        """Retrieve a key by ID. Returns None if missing or expired."""
        async with self._lock:
            key = self._keys.get(key_id)
            if key is None:
                return None
            if key.is_expired():
                del self._keys[key_id]
                return None
            return key

    async def rotate(self) -> int:
        """Explicitly rotate expired keys. Returns number of keys removed."""
        async with self._lock:
            return await self._purge_expired_locked()

    async def _purge_expired_locked(self) -> int:
        """Remove expired keys. Must be called with lock held."""
        now = time.time()
        expired_ids = [
            kid for kid, k in self._keys.items() if k.is_expired(now)
        ]
        for kid in expired_ids:
            del self._keys[kid]
        return len(expired_ids)

    async def size(self) -> int:
        """Current number of active (non-expired) keys."""
        async with self._lock:
            await self._purge_expired_locked()
            return len(self._keys)

    async def clear(self) -> None:
        """Remove all keys."""
        async with self._lock:
            self._keys.clear()


