class TestTTLBoundary:
    """INV-002: Expiry at exact threshold."""

    @pytest.mark.asyncio
    async def test_key_expires_at_exact_threshold(self):
        """Key is expired when now == expires_at."""
        now = 1000.0
        key = make_key("boundary", ttl_seconds=10, now=now)
        assert key.expires_at == 1010.0
        # Not expired before threshold
        assert key.is_expired(now=1009.999) is False
        # Expired at exact threshold
        assert key.is_expired(now=1010.0) is True
        # Expired after threshold
        assert key.is_expired(now=1010.001) is True

    @pytest.mark.asyncio
    async def test_buffer_removes_key_at_expiry(self, buffer: KeyRotationBuffer):
        """Buffer removes key exactly at expiry time."""
        now = time.time()
        key = make_key("expiring", ttl_seconds=0.1, now=now)
        await buffer.add_key(key)
        assert await buffer.get_key("expiring") is not None
        await asyncio.sleep(0.15)
        assert await buffer.get_key("expiring") is None

    @pytest.mark.asyncio
    async def test_rotation_removes_expired_keys(self, buffer: KeyRotationBuffer):
        """Explicit rotation purges expired keys."""
        now = time.time()
        await buffer.add_key(make_key("expired_1", ttl_seconds=0.05, now=now))
        await buffer.add_key(make_key("expired_2", ttl_seconds=0.05, now=now))
        await buffer.add_key(make_key("valid", ttl_seconds=60, now=now))
        await asyncio.sleep(0.1)
        removed = await buffer.rotate()
        assert removed == 2
        assert await buffer.size() == 1
        assert await buffer.get_key("valid") is not None


