class TestConcurrencySafety:
    """INV-002: Async operations are thread-safe under load."""

    @pytest.mark.asyncio
    async def test_concurrent_adds_never_exceed_capacity(self):
        """Concurrent additions never exceed capacity."""
        buf = KeyRotationBuffer(max_keys=10)
        tasks = [buf.add_key(make_key(f"key_{i}")) for i in range(100)]
        results = await asyncio.gather(*tasks)
        accepted = sum(1 for r in results if r is True)
        assert accepted <= 10
        assert await buf.size() <= 10

    @pytest.mark.asyncio
    async def test_concurrent_reads_and_writes(self):
        """Concurrent reads and writes maintain consistency."""
        buf = KeyRotationBuffer(max_keys=50)
        # Seed with some keys
        for i in range(20):
            await buf.add_key(make_key(f"seed_{i}"))

        async def writer():
            for i in range(30):
                await buf.add_key(make_key(f"writer_{i}"))

        async def reader():
            for i in range(30):
                await buf.get_key(f"seed_{i % 20}")

        await asyncio.gather(writer(), reader(), writer(), reader())
        assert await buf.size() <= 50

    @pytest.mark.asyncio
    async def test_concurrent_rotation_and_access(self):
        """Concurrent rotation and key access are safe."""
        buf = KeyRotationBuffer(max_keys=100)
        now = time.time()
        for i in range(50):
            await buf.add_key(make_key(f"key_{i}", ttl_seconds=0.05, now=now))

        async def rotator():
            for _ in range(10):
                await buf.rotate()
                await asyncio.sleep(0.01)

        async def accessor():
            for i in range(50):
                await buf.get_key(f"key_{i}")
                await asyncio.sleep(0.005)

        await asyncio.gather(rotator(), accessor(), rotator(), accessor())
        # After all operations, buffer should be consistent
        size = await buf.size()
        assert size >= 0
        assert size <= 100


