class TestPerformance:
    """Stress testing under realistic load."""

    @pytest.mark.asyncio
    async def test_high_volume_rotation(self):
        """Handle high-volume key rotation without degradation."""
        buf = KeyRotationBuffer(max_keys=1024)
        now = time.time()
        # Add 1000 keys with short TTL
        for i in range(1000):
            await buf.add_key(make_key(f"key_{i}", ttl_seconds=0.01, now=now))

        # Wait for expiry
        await asyncio.sleep(0.02)

        # Rotate all at once
        start = time.monotonic()
        removed = await buf.rotate()
        elapsed = time.monotonic() - start

        assert removed == 1000
        assert await buf.size() == 0
        # Rotation should complete quickly (< 1 second)
        assert elapsed < 1.0

    @pytest.mark.asyncio
    async def test_mixed_operations_under_load(self):
        """Mixed add/get/rotate operations under sustained load."""
        buf = KeyRotationBuffer(max_keys=100)
        now = time.time()

        async def worker(worker_id: int):
            for i in range(50):
                key_id = f"w{worker_id}_k{i}"
                await buf.add_key(make_key(key_id, ttl_seconds=0.05, now=now))
                await buf.get_key(key_id)
                if i % 10 == 0:
                    await buf.rotate()

        await asyncio.gather(*[worker(i) for i in range(10)])
        assert await buf.size() <= 100


